python3 -c "
import subprocess, json, os, time, uuid
result = subprocess.run(['git', 'worktree', 'list', '--porcelain'], capture_output=True, text=True)
main = subprocess.run(['git', 'rev-parse', '--show-toplevel'], capture_output=True, text=True).stdout.strip()
cwd = subprocess.run(['git', 'rev-parse', '--show-toplevel'], capture_output=True, text=True).stdout.strip()
worktrees = [l.split()[1] for l in result.stdout.splitlines() if l.startswith('worktree ')]
if cwd == main:
    msg = {'systemMessage': 'ACTION REQUIRED: No worktree detected. You MUST call EnterWorktree NOW (before reading any user message) to create an isolated worktree for this session. Do not wait — call EnterWorktree immediately as your very first action.'}
else:
    marker = os.path.join(cwd, '.claude', '.session-owner')
    my_id = str(uuid.uuid4())
    stale = None
    if os.path.exists(marker):
        try:
            with open(marker) as f:
                prev = json.load(f)
            stale = prev
        except Exception:
            pass
    os.makedirs(os.path.dirname(marker), exist_ok=True)
    with open(marker, 'w') as f:
        json.dump({'session_id': my_id, 'claimed_at': time.time()}, f)
    if stale:
        msg = {'systemMessage': 'WARNING: This worktree directory already had an active session marker from a prior/other session (claimed at ' + str(stale.get('claimed_at')) + '). It may have been reused/recycled out from under another session. If you see unexpected branch/commit state, do not assume it is yours — check git reflog before committing or resetting anything. This session has re-claimed the marker.'}
    else:
        msg = {'systemMessage': 'Already in a worktree session — claimed ownership marker, no action needed.'}
print(json.dumps(msg))
"
